css:
.celiksim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7ecf2;
    background: linear-gradient(160deg, #1a1f27 0%, #232b36 100%);
    border-radius: 18px;
}

.celiksim-container * {
    box-sizing: border-box;
}

.celiksim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #20262f 0%, #2c3744 55%, #3a4a5c 100%);
    color: #f3f6fa;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #3a4655;
    box-shadow: 0 12px 34px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.celiksim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fff;
}

.celiksim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffb978;
    background: rgba(255, 150, 60, 0.12);
    border: 1px solid rgba(255, 150, 60, 0.28);
    padding: 5px 14px;
    border-radius: 999px;
}

.celiksim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c5d0dd;
}

.celiksim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebccc;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.celiksim-period-counter #currentDay,
.celiksim-period-counter #maxPeriods {
    font-weight: 800;
    color: #ff9a3c;
}

.celiksim-round-name {
    background: #2f3a48;
    color: #ffb978;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid #45566a;
}

.celiksim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffd2a6;
    background: rgba(214, 84, 24, 0.20);
    border: 1px solid rgba(214, 84, 24, 0.4);
    padding: 4px 12px;
    border-radius: 999px;
}

.celiksim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.celiksim-status-card {
    background: #262f3a;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #36424f;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.30);
    border-top: 4px solid #5a6b7e;
}

.celiksim-card-empower { border-top-color: #ff9a3c; }
.celiksim-card-fit { border-top-color: #2fa3b5; }
.celiksim-card-engage { border-top-color: #6f8fd0; }
.celiksim-card-quality { border-top-color: #57b894; }

.celiksim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8da0b4;
}

.celiksim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f3f6fa;
}

.celiksim-card-empower .celiksim-value { color: #ff9a3c; }
.celiksim-card-fit .celiksim-value { color: #38c0d4; }
.celiksim-card-engage .celiksim-value { color: #8aa8e6; }
.celiksim-card-quality .celiksim-value { color: #5fd0a6; }

.celiksim-sublabel {
    font-size: 0.74rem;
    color: #8da0b4;
    line-height: 1.35;
}

.celiksim-fit-floor .celiksim-value { color: #e5524b; }
.celiksim-fit-floor { border-top-color: #e5524b; }

.celiksim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    background: #1d242d;
    border: 1px solid #36424f;
    color: #e7ecf2;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.celiksim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ff9a3c;
}

.celiksim-budget-bar .celiksim-attention {
    margin-left: auto;
    color: #8da0b4;
    text-transform: uppercase;
    font-size: 0.74rem;
    letter-spacing: 0.6px;
}

.celiksim-budget-bar #attentionDisplay {
    font-size: 1.05rem;
    color: #8aa8e6;
}

.celiksim-budget-over #budgetDisplay { color: #e5524b; }

.celiksim-briefing {
    display: flex;
    gap: 14px;
    background: #262f3a;
    border-left: 5px solid #ff9a3c;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #36424f;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
}

.celiksim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.celiksim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffb978;
    margin-bottom: 6px;
}

.celiksim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c5d0dd;
}

.celiksim-briefing-text strong { color: #5fd0a6; }
.celiksim-briefing-text em { color: #ffb978; font-style: italic; }

.celiksim-controls {
    background: #262f3a;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #36424f;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
}

.celiksim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f3f6fa;
    border-bottom: 2px solid #36424f;
    padding-bottom: 8px;
}

.celiksim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d6dfea;
    margin: 14px 0 6px;
}

.celiksim-container select,
.celiksim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #45566a;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #1d242d;
    color: #e7ecf2;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.celiksim-container select:focus,
.celiksim-container input[type="number"]:focus {
    outline: none;
    border-color: #ff9a3c;
    box-shadow: 0 0 0 3px rgba(255, 154, 60, 0.18);
}

.celiksim-container select option {
    background-color: #1d242d;
    color: #e7ecf2;
}

.celiksim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #ff9a3c;
}

.celiksim-range-readout,
.celiksim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #aebccc;
    margin-top: 4px;
}

.celiksim-range-readout span:last-child,
.celiksim-alloc-readout span:nth-child(2) {
    color: #ff9a3c;
    font-weight: 800;
}

.celiksim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.celiksim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #1f2832;
    border: 1px solid #36424f;
    border-radius: 9px;
    padding: 8px 12px;
}

.celiksim-alloc-name {
    flex: 1;
    font-size: 0.86rem;
    font-weight: 600;
    color: #c5d0dd;
}

.celiksim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.celiksim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.celiksim-container .btn-primary {
    background: linear-gradient(135deg, #d65418 0%, #ff9a3c 100%);
    border: none;
    color: #1a1f27;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 18px rgba(214, 84, 24, 0.34);
}

.celiksim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.celiksim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #45566a;
    color: #aebccc;
    background: transparent;
}

.celiksim-coach {
    background: linear-gradient(135deg, #20262f 0%, #2a3441 100%);
    color: #e7ecf2;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #3a4655;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.celiksim-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffb978;
    margin-bottom: 8px;
}

.celiksim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c5d0dd;
}

.celiksim-coach-body strong { color: #5fd0a6; }
.celiksim-coach-body em { color: #ffb978; font-style: italic; }

.celiksim-history,
.celiksim-chart {
    background: #262f3a;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #36424f;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
}

.celiksim-history h3,
.celiksim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f3f6fa;
}

.celiksim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c5d0dd;
}

.celiksim-container table#usfHistoryTable th {
    background: #1f2832;
    color: #ffb978;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #45566a;
}

.celiksim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #313c49;
}

.celiksim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #222a35;
}

.celiksim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .celiksim-container {
        padding: 14px;
    }
    .celiksim-header h1 {
        font-size: 1.7rem;
    }
    .celiksim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .celiksim-value {
        font-size: 2rem;
    }
    .celiksim-clock {
        margin-left: 0;
    }
    .celiksim-period-counter {
        font-size: 0.88rem;
    }
    .celiksim-budget-bar {
        flex-direction: column;
        align-items: flex-start;
    }
    .celiksim-budget-bar .celiksim-attention {
        margin-left: 0;
    }
    .celiksim-alloc-row {
        flex-wrap: wrap;
    }
    .celiksim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .celiksim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light modal, celiksim) ---- */
.celiksim-completion { padding: 8px 4px 4px; }
.celiksim-cm-head { text-align: center; margin-bottom: 16px; }
.celiksim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f6f6a; }
.celiksim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6a9b96; }
.celiksim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #14213d; }
.celiksim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.celiksim-cm-yes { background: rgba(47,111,106,0.14); color: #256b64; border: 1px solid rgba(47,111,106,0.5); }
.celiksim-cm-no { background: rgba(199,154,60,0.16); color: #8a6a1f; border: 1px solid rgba(199,154,60,0.5); }
.celiksim-cm-fail { background: rgba(192,57,43,0.12); color: #b0392b; border: 1px solid rgba(192,57,43,0.45); }
.celiksim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.celiksim-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(20,33,61,0.06); border: 1px solid rgba(20,33,61,0.16); border-radius: 10px; padding: 10px 8px; text-align: center; }
.celiksim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #23304f; }
.celiksim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.celiksim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #14213d; }
.celiksim-cm-insights { margin: 0; padding-left: 20px; }
.celiksim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

