(function() {
    'use strict';

    class CelikAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `From Power to Empowerment`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Türkiye / TRY).
            this.START_EMPOWER = 31;     // Empowerment Index now
            this.START_FIT = 60;         // Cultural-Fit starts healthy; flatness can collapse it
            this.START_ENGAGE = 38;      // engagement low; attrition 18%/yr
            this.START_QUALITY = 42;     // quality cost ≈ ₺220M/yr, trending up
            this.FIT_FLOOR = 50;         // honour local norms or supervisors resist
            this.EMPOWER_TARGET = 70;    // credible day-90 trajectory
            this.BUDGET_CAP = 60;        // ₺60M change budget, in millions
            this.ATTENTION_CAP = 10;     // limited manager attention units

            // Concept truths.
            this.TRUE_ROOT = `control`;
            this.TRUE_NORM = `paternalism`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    empower: this.START_EMPOWER,
                    fit: this.START_FIT,
                    engage: this.START_ENGAGE,
                    quality: this.START_QUALITY,
                    budgetUsed: 0,
                    attentionUsed: 0,
                    fitBelowFloor: false,
                    voiceUndermined: false,
                    overclaimed: false,
                    empowerHistory: [this.START_EMPOWER],
                    fitHistory: [this.START_FIT],
                    engageHistory: [this.START_ENGAGE],
                    qualityHistory: [this.START_QUALITY],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults mirror the first (pre-selected) option of each control,
                // which are deliberately the plausible-but-WRONG choices — a click-through
                // must not auto-win. The learner has to actively choose the correct levers.
                state.decisions = {
                    root: `quality`,
                    norm: `flat`,
                    link: 50,
                    load: `overload`,
                    delegation: 20,
                    voice: 20,
                    recognition: 20,
                    frame: `mandate`,
                    incident: `retract`,
                    veteran: `overrule`,
                    visit: `transformed`,
                    protect: 50,
                    measure: `lagonly`,
                    sustain: `central`,
                    board: `overpromise`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const norm = document.getElementById(`normInput`);
                const link = document.getElementById(`linkInput`);
                if (root) decisions.root = root.value;
                if (norm) decisions.norm = norm.value;
                if (link) decisions.link = parseInt(link.value, 10);
                if (!Number.isFinite(decisions.link) || decisions.link < 0 || decisions.link > 100) {
                    warn(`warn_link_range`); return false;
                }
            } else if (round === 2) {
                const load = document.getElementById(`loadInput`);
                const frame = document.getElementById(`frameInput`);
                if (load) decisions.load = load.value;
                if (frame) decisions.frame = frame.value;
                const del = document.getElementById(`delegationInput`);
                const voi = document.getElementById(`voiceInput`);
                const rec = document.getElementById(`recognitionInput`);
                if (del) decisions.delegation = parseFloat(del.value);
                if (voi) decisions.voice = parseFloat(voi.value);
                if (rec) decisions.recognition = parseFloat(rec.value);
                const parts = [decisions.delegation, decisions.voice, decisions.recognition];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(decisions.delegation + decisions.voice + decisions.recognition);
                if (total !== this.BUDGET_CAP) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const inc = document.getElementById(`incidentInput`);
                const vet = document.getElementById(`veteranInput`);
                const vis = document.getElementById(`visitInput`);
                const pr = document.getElementById(`protectInput`);
                if (inc) decisions.incident = inc.value;
                if (vet) decisions.veteran = vet.value;
                if (vis) decisions.visit = vis.value;
                if (pr) decisions.protect = parseInt(pr.value, 10);
                if (!Number.isFinite(decisions.protect) || decisions.protect < 0 || decisions.protect > 100) {
                    warn(`warn_protect_range`); return false;
                }
            } else if (round === 4) {
                const me = document.getElementById(`measureInput`);
                const su = document.getElementById(`sustainInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (me) decisions.measure = me.value;
                if (su) decisions.sustain = su.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Four dials move on their own deltas. empower = the headline change;
            // fit = whether the change honours local norms; engage = belief on the floor;
            // quality = whether voice is actually catching defects.
            let empowerDelta = 0, fitDelta = 0, engageDelta = 0, qualityDelta = 0;
            let spend = 0, attention = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: a leadership/control problem, not a quality-tools/training/people problem.
                if (d.root === this.TRUE_ROOT) {
                    empowerDelta += 6; engageDelta += 3; qualityDelta += 2; coachKey = `coach_r1_root_right`;
                } else if (d.root === `quality`) {
                    empowerDelta -= 5; qualityDelta -= 2; coachKey = `coach_r1_quality`;
                } else if (d.root === `training`) {
                    empowerDelta -= 3; engageDelta -= 2; coachKey = `coach_r1_training`;
                } else {
                    empowerDelta -= 6; engageDelta -= 4; coachKey = `coach_r1_individuals`;
                }

                // Local norm: work WITH paternalist care & hierarchy. A flat model
                // collapses Cultural-Fit (Decision Tree: -14 fit).
                if (d.norm === this.TRUE_NORM) {
                    fitDelta += 7; empowerDelta += 3; engageDelta += 2;
                    if (d.root === this.TRUE_ROOT) coachKey = `coach_r1_diag_sharp`;
                } else if (d.norm === `flat`) {
                    fitDelta -= 14; empowerDelta += 1; engageDelta -= 4; coachKey = `coach_r1_flat`;
                } else if (d.norm === `pay`) {
                    fitDelta -= 4; engageDelta += 1; coachKey = `coach_r1_pay`;
                } else {
                    fitDelta -= 6; empowerDelta -= 2; coachKey = `coach_r1_seniority`;
                }

                // Clarity that voice (not checklists) fixes silence.
                if (d.link >= 60) { empowerDelta += 4; qualityDelta += 2; }
                else if (d.link <= 25) { empowerDelta -= 4; qualityDelta -= 3; coachKey = `coach_r1_lowlink`; }

                summaryKey = (d.root === this.TRUE_ROOT && d.norm === this.TRUE_NORM) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Sequence levers under limited attention; do not pile everything on.
                switch (d.load) {
                    case `sequenced`: attention += 6; empowerDelta += 4; engageDelta += 4; coachKey = `coach_r2_sequenced`; break;
                    case `overload`: attention += 14; empowerDelta -= 6; engageDelta -= 6; qualityDelta -= 3; coachKey = `coach_r2_overload`; break;
                    case `one`: attention += 3; empowerDelta += 1; engageDelta += 1; coachKey = `coach_r2_one`; break;
                }

                // Budget allocation. Voice is the central lever — the audit says silence
                // caused the escape. Delegation (line-stop) is the quality fix. Recognition
                // reinforces. Starving voice or over-funding any one lever underperforms.
                const del = d.delegation, voi = d.voice, rec = d.recognition;
                empowerDelta += Math.min(5, del * 0.20);        // delegation lifts empowerment
                qualityDelta += Math.min(6, del * 0.24);        // ...and catches defects
                empowerDelta += Math.min(6, voi * 0.24);        // voice is the strongest empowerment lever
                qualityDelta += Math.min(5, voi * 0.22);        // silence caught early = quality
                engageDelta += Math.min(6, rec * 0.34);         // recognition drives engagement
                empowerDelta += Math.min(3, rec * 0.15);

                if (voi < 14) { qualityDelta -= 6; engageDelta -= 3; coachKey = `coach_r2_novoice`; }
                else if (voi >= 20 && del >= 16 && rec >= 10) { engageDelta += 2; coachKey = (d.load === `sequenced`) ? `coach_r2_balanced` : coachKey; }
                if (del < 10) { qualityDelta -= 4; coachKey = `coach_r2_nodelegation`; }
                if (rec === 0) { engageDelta -= 4; }

                // Framing: empowerment AS paternalist care beats mandate (paper) and a
                // Western flat model (dishonours hierarchy → Cultural-Fit hit).
                switch (d.frame) {
                    case `care`: fitDelta += 7; empowerDelta += 3; engageDelta += 3; if (coachKey === `coach_default`) coachKey = `coach_r2_care`; break;
                    case `mandate`: fitDelta -= 4; engageDelta -= 5; empowerDelta -= 3; coachKey = `coach_r2_mandate`; break;
                    case `western`: fitDelta -= 12; empowerDelta += 1; engageDelta -= 3; coachKey = `coach_r2_western`; break;
                }

                spend = this.BUDGET_CAP; // the allocation always commits the full change budget

                summaryKey = (d.load === `sequenced` && d.frame === `care` && voi >= 18) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // The live test: reinforce delegated authority through an imperfect first use.
                switch (d.incident) {
                    case `reinforce`: empowerDelta += 5; engageDelta += 5; qualityDelta += 3; coachKey = `coach_r3_reinforce`; break;
                    case `retract`: empowerDelta -= 11; engageDelta -= 8; qualityDelta -= 4; coachKey = `coach_r3_retract`; break;
                    case `quiet`: empowerDelta -= 6; engageDelta -= 5; coachKey = `coach_r3_quiet`; break;
                }

                // The veteran power-holder: convert him into an owner, not a victim.
                switch (d.veteran) {
                    case `owner`: fitDelta += 8; empowerDelta += 3; engageDelta += 3; if (d.incident === `reinforce`) coachKey = `coach_r3_owner`; break;
                    case `overrule`: fitDelta -= 11; engageDelta -= 4; coachKey = `coach_r3_overrule`; break;
                    case `bypass`: fitDelta -= 6; empowerDelta -= 3; coachKey = `coach_r3_bypass`; break;
                }

                // The customer visit: honest early behaviours beat declaring victory or hiding.
                switch (d.visit) {
                    case `progress`: qualityDelta += 4; empowerDelta += 2; break;
                    case `transformed`: qualityDelta -= 5; coachKey = `coach_r3_transformed`; ds.overclaimed = true; break;
                    case `hide`: qualityDelta -= 6; engageDelta -= 3; coachKey = `coach_r3_hide`; break;
                }

                // Protect frontline & coaching time so supervisors can embed the change.
                if (d.protect >= 60) { empowerDelta += 4; engageDelta += 4; fitDelta += 2; }
                else if (d.protect <= 25) { empowerDelta -= 5; engageDelta -= 6; coachKey = `coach_r3_noprotect`; }

                summaryKey = (d.incident === `reinforce` && d.veteran === `owner` && d.visit === `progress`) ? `sum_r3_good`
                    : (d.incident === `retract` ? `sum_r3_punish` : `sum_r3_weak`);
            } else if (round === 4) {
                // Embed, measure, defend honestly.
                switch (d.measure) {
                    case `leadlag`: empowerDelta += 4; qualityDelta += 5; engageDelta += 2; coachKey = `coach_r4_leadlag`; break;
                    case `lagonly`: qualityDelta += 1; coachKey = `coach_r4_lagonly`; break;
                    case `vanity`: engageDelta -= 6; empowerDelta -= 5; coachKey = `coach_r4_vanity`; break;
                }

                // Sustainment after attention moves on — supervisors as owners.
                switch (d.sustain) {
                    case `supervisors`: empowerDelta += 5; fitDelta += 4; engageDelta += 3; break;
                    case `central`: empowerDelta -= 5; engageDelta -= 3; coachKey = `coach_r4_central`; break;
                    case `nobody`: empowerDelta -= 10; engageDelta -= 6; coachKey = `coach_r4_nobody`; break;
                }

                // The board / customer challenge: honest pacing vs overpromising vs coercion.
                switch (d.board) {
                    case `honest`: empowerDelta += 4; fitDelta += 3; qualityDelta += 3; if (d.sustain === `supervisors`) coachKey = `coach_r4_honest`; break;
                    case `overpromise`: qualityDelta -= 8; fitDelta -= 4; coachKey = `coach_r4_overpromise`; ds.overclaimed = true; break;
                    case `coerce`: fitDelta -= 8; engageDelta -= 7; empowerDelta -= 4; coachKey = `coach_r4_coerce`; break;
                }

                empowerDelta += Math.round((d.conviction - 60) / 15);

                summaryKey = (d.measure === `leadlag` && d.sustain === `supervisors` && d.board === `honest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round(ds.budgetUsed + spend));
            ds.attentionUsed = Math.min(this.ATTENTION_CAP, Math.round(ds.attentionUsed + attention));

            // Apply deltas with 0–100 clamps (start low, modest deltas → headroom to round 4).
            ds.empower = Math.max(0, Math.min(100, ds.empower + empowerDelta));
            ds.fit = Math.max(0, Math.min(100, ds.fit + fitDelta));
            ds.engage = Math.max(0, Math.min(100, ds.engage + engageDelta));
            ds.quality = Math.max(0, Math.min(100, ds.quality + qualityDelta));

            if (ds.fit < this.FIT_FLOOR) ds.fitBelowFloor = true;
            if (d.incident === `retract` || (round === 4 && d.board === `coerce`)) ds.voiceUndermined = true;

            ds.empowerHistory.push(Math.round(ds.empower));
            ds.fitHistory.push(Math.round(ds.fit));
            ds.engageHistory.push(Math.round(ds.engage));
            ds.qualityHistory.push(Math.round(ds.quality));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                empower: Math.round(ds.empower),
                empowerDelta: Math.round(empowerDelta),
                fit: Math.round(ds.fit),
                fitDelta: Math.round(fitDelta),
                engage: Math.round(ds.engage),
                engageDelta: Math.round(engageDelta),
                quality: Math.round(ds.quality),
                qualityDelta: Math.round(qualityDelta),
                budgetUsed: ds.budgetUsed,
                attentionUsed: ds.attentionUsed,
                fitBelowFloor: ds.fitBelowFloor,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

