            // Budget allocation live total (must total ₺60M).
            const self = this;
            const allocIds = [`delegationInput`, `voiceInput`, `recognitionInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = `₺` + total + `M`;
                const bar = document.querySelector(`.celiksim-alloc-readout`);
                if (bar) bar.style.color = (total !== self.BUDGET_CAP) ? `#e5524b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

