        _composite(ds) {
            const empower = Math.round(ds.empower);
            const fit = Math.round(ds.fit);
            const engage = Math.round(ds.engage);
            const quality = Math.round(ds.quality);
            const composite = Math.round(empower * 0.30 + fit * 0.25 + engage * 0.22 + quality * 0.23);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.sound
                ? `<span class="celiksim-cm-badge celiksim-cm-yes">` + T(`cm_sound`) + `</span>`
                : `<span class="celiksim-cm-badge celiksim-cm-no">` + T(`cm_notsound`) + `</span>`;
            let failBadges = ``;
            if (s.voiceUndermined) failBadges += ` <span class="celiksim-cm-badge celiksim-cm-fail">` + T(`cm_voice`) + `</span>`;
            if (s.overclaimed) failBadges += ` <span class="celiksim-cm-badge celiksim-cm-fail">` + T(`cm_overclaim`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="celiksim-cm-metric"><span class="celiksim-cm-mv">` + Math.round(s.empower || 0) + `</span><span class="celiksim-cm-ml">` + T(`cm_m_empower`) + `</span></div>`
                + `<div class="celiksim-cm-metric"><span class="celiksim-cm-mv">` + Math.round(s.fit || 0) + `</span><span class="celiksim-cm-ml">` + T(`cm_m_fit`) + `</span></div>`
                + `<div class="celiksim-cm-metric"><span class="celiksim-cm-mv">` + Math.round(s.engage || 0) + `</span><span class="celiksim-cm-ml">` + T(`cm_m_engage`) + `</span></div>`
                + `<div class="celiksim-cm-metric"><span class="celiksim-cm-mv">` + Math.round(s.quality || 0) + `</span><span class="celiksim-cm-ml">` + T(`cm_m_quality`) + `</span></div>`;
            return ``
                + `<div class="celiksim-completion">`
                +   `<div class="celiksim-cm-head">`
                +     `<div class="celiksim-cm-score">` + score + `<span class="celiksim-cm-score-max">/100</span></div>`
                +     `<div class="celiksim-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="celiksim-cm-metrics">` + metrics + `</div>`
                +   `<div class="celiksim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="celiksim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const empower = Math.round(ds.empower);
            const fit = Math.round(ds.fit);
            const engage = Math.round(ds.engage);
            const quality = Math.round(ds.quality);

            const hitTarget = empower >= this.EMPOWER_TARGET;
            const fitHeld = fit >= this.FIT_FLOOR;
            const realChange = hitTarget && fitHeld && engage >= 55 && quality >= 55;
            const composite = this._composite(ds);

            let performanceKey = `grade_stuck`;
            if (realChange && composite >= 72) performanceKey = `grade_lasts`;
            else if (hitTarget && fitHeld) performanceKey = `grade_credible`;
            else if (hitTarget && !fitHeld) performanceKey = `grade_norespect`;
            else if (empower > this.START_EMPOWER + 18) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (realChange) insights.push(window.mySimulation.t(`insight_embedded`));
            else if (hitTarget && !fitHeld) insights.push(window.mySimulation.t(`insight_norespect`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!fitHeld) insights.push(window.mySimulation.t(`insight_fitfloor`));
            if (ds.voiceUndermined) insights.push(window.mySimulation.t(`insight_voicekilled`));
            if (ds.overclaimed) insights.push(window.mySimulation.t(`insight_overclaim`));
            if (realChange && fit >= 65) insights.push(window.mySimulation.t(`insight_coexist`));

            return {
                empower: empower,
                fit: fit,
                engage: engage,
                quality: quality,
                hitTarget: hitTarget,
                fitHeld: fitHeld,
                sound: realChange,
                voiceUndermined: ds.voiceUndermined,
                overclaimed: ds.overclaimed,
                composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.fitBelowFloor) return window.mySimulation.t(`hint_fit`);
            if (ds.voiceUndermined) return window.mySimulation.t(`hint_voice`);
            if (ds.engage < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_engage`);
            if (state.currentPeriod >= 3 && ds.empower < 50) return window.mySimulation.t(`hint_behind`);
            if (ds.empower >= this.EMPOWER_TARGET && ds.fit >= this.FIT_FLOOR && ds.engage >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

